export const SITE_JS = "const $=id=>document.getElementById(id);\nconst state={user:null,plan:'trial',lang:'en'};\nconst tr={\n 'fa':{'nav-system':'سیستم','nav-plans':'اشتراک‌ها','nav-setup':'روش استفاده','hero-label':'هوشمندی برای هر سیگنال','hero-1':'دقت.','hero-2':'بدون سازش.','hero-desc':'اکوسیستم حرفه‌ای معاملات؛ اتصال مستقیم سیگنال‌های تریدینگ‌ویو و تلگرام به متاتریدر ۵، مجموعه ۵۲ اندیکاتور پریمیوم و مدیریت همه امکانات در داشبورد اختصاصی.','start':'مشاهده اشتراک‌ها','explore':'معرفی پلتفرم','stat1':'اکسپرت برای نصب','stat2':'اندیکاتور پریمیوم*','stat3':'زیرساخت ابری','system-title':'استانداردی جدید برای اجرای سیگنال','system-desc':'یک محیط حرفه‌ای که مراحل غیرضروری بین دریافت سیگنال و اجرای آن در متاتریدر را حذف می‌کند.','f1-title':'سیگنال‌بریج مستقیم','f1-desc':'یک اکسپرت EX5 و یک وب‌هوک تریدینگ‌ویو؛ بدون برنامه واسط ویندوز در معماری مستقیم.','f2-title':'۵۲ اندیکاتور پریمیوم','f2-desc':'ابزارهای اختصاصی همراه اشتراک سه‌ماهه و سالانه؛ دانلود فایل‌های هر اندیکاتور پس از آماده‌شدن نسخه تأییدشده فعال می‌شود.','f3-title':'یک هویت امن','f3-desc':'با ایمیل یا ربات تلگرام ثبت‌نام کنید و مجوز، اشتراک و حساب MT5 را در یک داشبورد مدیریت کنید.','pricing-title':'اشتراک متناسب با هدف شما','pricing-desc':'اشتراک‌های واضح و نصب آسان. ابتدا رایگان شروع کنید.','p1':'آزمایشی رایگان','p1d':'تجربه اتصال سیگنال‌بریج','p1f1':'یک ماه دسترسی سیگنال‌بریج','p1f2':'سریال اختصاصی اکسپرت','p1f3':'داشبورد اختصاصی','p1f4':'ثبت‌نام با ایمیل یا تلگرام','p1cta':'شروع رایگان ←','p2':'پریمیوم سه‌ماهه','p2d':'مجموعه کامل اندیکاتورها','p2f1':'۳ ماه اشتراک سیگنال‌بریج','p2f2':'۵۲ اندیکاتور پریمیوم','p2f3':'سریال شخصی فعال‌سازی','p2f4':'مدیریت اشتراک','p2cta':'انتخاب سه‌ماهه ←','p3':'الیت سالانه','p3d':'برای معامله‌گرانی که بیش از ابزار می‌خواهند','p3f1':'یک سال اشتراک سیگنال‌بریج','p3f2':'همه ۵۲ اندیکاتور پریمیوم','p3f3':'امکان شخصی‌سازی اندیکاتورها','p3f4':'مشاوره با تیم فنی','p3cta':'انتخاب سالانه ←','how-title':'از ثبت‌نام تا دریافت سیگنال در چهار مرحله','step1':'ساخت حساب','step1d':'تأیید ایمیل یا شروع ربات تلگرام','step2':'دریافت سریال اختصاصی','step2d':'یک کد فعال‌سازی برای حساب MT5 شما','step3':'نصب یک فایل EX5','step3d':'کپی اکسپرت در پوشه MQL5/Experts','step4':'تأیید و فعال‌سازی','step4d':'آدرس سرور را در MT5 مجاز و سریال را در اولین ورودی EA وارد کنید.'}\n};\nconst notice=(msg,kind='')=>{const t=$('toast');t.textContent=msg;t.classList.remove('hidden');window.clearTimeout(notice.timer);notice.timer=setTimeout(()=>t.classList.add('hidden'),4800);};\nconst status=(id,msg,error=false)=>{const e=$(id);e.textContent=msg;e.className='message '+(error?'error':'success');};\nasync function call(path,method='GET',body=null){\n const options={method,headers:{'accept':'application/json'}};\n if(body!==null){options.headers['content-type']='application/json';options.body=JSON.stringify(body);}\n const response=await fetch(path,options);let data;\n try{data=await response.json();}catch{throw Error('INVALID_RESPONSE');}\n if(!response.ok)throw Error(data?.error||'SERVICE_UNAVAILABLE');\n return data;\n}\nconst show=id=>{const e=$(id);e.classList.remove('hidden');e.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';};\nconst hide=id=>{const e=$(id);e.classList.add('hidden');e.setAttribute('aria-hidden','true');if(document.querySelectorAll('.overlay:not(.hidden)').length===0)document.body.style.overflow='';};\nfunction openAuth(){hide('portalOverlay');show('authOverlay');$('email').focus();}\nasync function openPortal(){hide('authOverlay');show('portalOverlay');await refreshProfile();}\nasync function refreshProfile(){\n try{state.user=(await call('/api/me')).user;}\n catch{hide('portalOverlay');openAuth();return;}\n const u=state.user;\n $('portalIdentity').textContent=u.email||u.telegram||'DrFX client';\n $('userPlan').textContent=({trial:'Free trial',quarterly:'Quarterly Premium',annual:'Annual Elite'})[u.plan]||u.plan;\n $('licenseDates').textContent=u.expires_at?'Expires: '+u.expires_at:'Starts at first MT5 activation';\n $('licenseStatus').textContent=u.license_status==='active'?'● ACTIVE':'● INACTIVE';\n $('linkedMT5').textContent=u.mt5_account?'MT5 #'+u.mt5_account.login+' / '+u.mt5_account.server:'MT5 account not bound yet';\n $('libraryStatus').textContent=u.plan==='trial'?'Not in trial':'Coming soon';\n $('serial').textContent=u.activation_code||'UNAVAILABLE';\n $('adminPanel').classList.toggle('hidden',u.role!=='admin');\n if(u.role==='admin')await refreshAdmin();\n}\nasync function refreshAdmin(){\n try{\n  const [stats,data]=await Promise.all([call('/api/admin/stats'),call('/api/admin/users?q='+encodeURIComponent($('adminSearch').value||''))]);\n  $('adminStats').replaceChildren();\n  for(const [key,val] of Object.entries(stats.stats||{})){\n   const el=document.createElement('div');const k=document.createElement('b');k.textContent=String(val??0);el.append(key+': ',k);$('adminStats').append(el);\n  }\n  const rows=$('adminRows');rows.replaceChildren();\n  for(const u of data.users||[]){\n   const tr=document.createElement('tr'),identity=document.createElement('td'),meta=document.createElement('small');\n   identity.textContent=u.email||u.telegram_name||u.telegram_id||'User';meta.textContent=u.id;identity.append(meta);\n   const plan=document.createElement('td');plan.textContent=u.plan;\n   const current=document.createElement('td');current.textContent=u.status;\n   const action=document.createElement('td'),sel=document.createElement('select'),button=document.createElement('button');\n   for(const item of ['grant_trial','grant_quarterly','grant_annual','suspend','resume','revoke_license']){\n    const option=document.createElement('option');option.value=item;option.textContent=item.replaceAll('_',' ');sel.append(option);\n   }\n   button.textContent='Apply';button.addEventListener('click',async()=>{if(!confirm('Apply '+sel.value+' to '+u.id+'?'))return;\n    try{await call('/api/admin/user','POST',{user_id:u.id,action:sel.value});status('adminMsg','User updated');await refreshAdmin();}\n    catch(e){status('adminMsg',e.message,true);}\n   });action.append(sel,button);tr.append(identity,plan,current,action);rows.append(tr);\n  }\n }catch(e){status('adminMsg',e.message,true);}\n}\nasync function checkout(plan){\n if(!state.user){state.plan=plan;openAuth();return;}\n if(plan==='trial'){await openPortal();return;}\n try{const p=await call('/api/checkout','POST',{plan});const url=new URL(p.invoice_url);\n  if(url.protocol!=='https:'||!url.hostname.endsWith('nowpayments.io'))throw Error('INVALID_GATEWAY_URL');\n  location.assign(url.href);\n }catch(e){notice(e.message==='PAYMENTS_NOT_CONFIGURED'?'Secure payments will open after merchant verification.':e.message);}\n}\n$('loginOpen').onclick=async()=>{try{await refreshProfile();if(state.user)show('portalOverlay');}catch{openAuth();}};\n$('bottomJoin').onclick=$('loginOpen').onclick;\ndocument.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>checkout(b.dataset.plan)));\ndocument.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>hide(b.dataset.close));\n$('portalClose').onclick=()=>hide('portalOverlay');\n$('authOverlay').addEventListener('click',e=>{if(e.target===$('authOverlay'))hide('authOverlay')});\n$('portalOverlay').addEventListener('click',e=>{if(e.target===$('portalOverlay'))hide('portalOverlay')});\ndocument.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{\n document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));\n $('emailTab').classList.toggle('hidden',b.dataset.tab!=='email');\n $('telegramTab').classList.toggle('hidden',b.dataset.tab!=='telegram');\n});\n$('sendEmail').onclick=async()=>{\n const email=$('email').value.trim();\n try{await call('/api/auth/email/start','POST',{email});status('authMsg','Sign-in code sent to your email.');}\n catch(e){status('authMsg',e.message,true);}\n};\n$('verifyEmail').onclick=async()=>{\n try{await call('/api/auth/email/verify','POST',{email:$('email').value.trim(),code:$('emailCode').value.trim()});await openPortal();}\n catch(e){status('authMsg',e.message,true);}\n};\n$('loginTelegram').onclick=async()=>{\n try{await call('/api/auth/telegram/code','POST',{code:$('tgCode').value.trim()});await openPortal();}\n catch(e){status('authMsg',e.message,true);}\n};\n$('copySerial').onclick=async()=>{if(!state.user?.activation_code)return;try{await navigator.clipboard.writeText(state.user.activation_code);notice('Activation code copied.');}catch{notice('Clipboard permission denied.')}};\n$('rotateSerial').onclick=async()=>{if(!confirm('The current EA serial will stop working. Regenerate?'))return;try{await call('/api/license/rotate','POST',{});await refreshProfile();notice('New activation code issued.');}catch(e){status('portalMsg',e.message,true);}};\n$('linkTelegram').onclick=async()=>{try{const r=await call('/api/auth/link/create','POST',{});status('portalMsg','Send /link '+r.code+' to your DrFX Telegram bot within 10 minutes.');}catch(e){status('portalMsg',e.message,true);}};\n$('logout').onclick=async()=>{try{await call('/api/auth/logout','POST',{});}finally{state.user=null;hide('portalOverlay');notice('Signed out.');}};\n$('reloadAdmin').onclick=refreshAdmin;\n$('adminSearch').onchange=refreshAdmin;\n$('lang').onclick=()=>{\n state.lang=state.lang==='en'?'fa':'en';\n document.body.setAttribute('dir',state.lang==='fa'?'rtl':'ltr');\n document.documentElement.lang=state.lang;\n for(const [key,en] of Object.entries(english)){const e=document.querySelector('[data-i=\"'+key+'\"]');if(e)e.textContent=state.lang==='fa'?(tr.fa[key]||en):en;}\n $('lang').textContent=state.lang==='en'?'FA ↔ EN':'EN ↔ FA';\n};\nconst english={};document.querySelectorAll('[data-i]').forEach(e=>english[e.dataset.i]=e.textContent);\nwindow.addEventListener('keydown',e=>{if(e.key==='Escape'){hide('authOverlay');hide('portalOverlay')}});\n(async()=>{try{const r=await call('/api/me');state.user=r.user;}catch{state.user=null;}\n if(new URLSearchParams(location.search).get('paid')==='processing')notice('Payment is being verified. Your plan updates after confirmation.');\n})();\nconst candleGroup=$('candles');if(candleGroup){\n const c=[128,118,122,110,113,98,95,100,90,83,88,75,73,62,70,57,54,63,49,52,39,45,32,28,31,22];\n c.forEach((v,i)=>{const x=18+i*25,up=i===0||v<=c[i-1],base=v+20,hi=v-10-(i%3)*3,lo=base+13+(i%4)*2,col=up?'#85d5bb':'#dc8d90';\n  const wick=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,value] of Object.entries({x1:x,x2:x,y1:hi,y2:lo,stroke:col,'stroke-width':1.5}))wick.setAttribute(k,value);\n  const box=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [k,value] of Object.entries({x:x-5,y:up?v:base-10,width:10,height:up?20:10,fill:col,opacity:.83}))box.setAttribute(k,value);\n  candleGroup.append(wick,box);\n });\n}\n\n\nconst globeClips=[...document.querySelectorAll('[data-motion-video]')];\nconst prefersReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');\nif(!prefersReducedMotion.matches && !navigator.connection?.saveData){\n const globeObserver='IntersectionObserver' in window?new IntersectionObserver(entries=>{entries.forEach(entry=>{\n  const v=entry.target;if(entry.isIntersecting && document.visibilityState==='visible'){\n   if(!v.src)v.src=v.dataset.videoSource;\n   v.play().catch(()=>{});\n  }else v.pause();\n })},{rootMargin:'150px 0px',threshold:0.05}):null;\n globeClips.forEach(video=>{\n  video.addEventListener('error',()=>{video.dataset.mediaUnavailable='true';video.pause()});\n  if(globeObserver)globeObserver.observe(video);\n  else{video.src=video.dataset.videoSource;video.play().catch(()=>{})}\n });\n document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')globeClips.forEach(v=>v.pause())});\n prefersReducedMotion.addEventListener('change',e=>{if(e.matches)globeClips.forEach(v=>v.pause())});\n}\n";
